const css = `
.j180{min-height:100dvh;background:#e7e4de;color:#07233c;padding:24px 16px 40px}
.j180-card{max-width:941px;margin:0 auto;background:#fffdf7;box-shadow:0 8px 40px #1232;border-radius:24px;overflow:hidden}
.j180-head{display:grid;justify-items:center;gap:12px;text-align:center;padding:36px 20px 8px}
.j180-head img{width:min(66vw,300px);height:auto}
.j180-head h1{margin:0;font-size:clamp(26px,5vw,38px);font-weight:800;line-height:1.2}
.j180-head p{margin:0;font-size:clamp(16px,2.6vw,20px);font-weight:500;color:#3d4b54;line-height:1.7}
.j180-orn{display:flex;align-items:center;gap:6px;width:min(60%,260px)}
.j180-orn i{flex:1;height:2px;background:#c89c4c}.j180-orn b{width:7px;height:7px;border-radius:50%;background:#c89c4c}
.j180-orn b.big{width:11px;height:11px}
.j180-body{padding:20px clamp(16px,5.75%,54px) 28px}
.j180-sec{border:1px solid #c89c4c;border-radius:22px;overflow:hidden;background:#fff}
.j180-sec h2{margin:0;display:flex;align-items:center;gap:12px;background:linear-gradient(110deg,#076a87,#005577);color:#fff;font-size:clamp(19px,3.2vw,28px);font-weight:800;padding:12px 20px;min-height:58px}
.j180-sec h2 svg{color:#d3ab5c;flex:none}
.j180-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;padding:16px}
@media (min-width:768px){.j180-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;padding:20px}}
.j180-tile{display:flex;flex-direction:column;align-items:center;gap:8px;text-align:center;padding:16px 8px 14px;min-height:150px;border:1px solid #e3d3b0;border-radius:18px;background:#fffdf7;color:#07233c;text-decoration:none;transition:transform .18s ease-out,box-shadow .18s ease-out,border-color .18s ease-out}
a.j180-tile:hover{transform:translateY(-2px);box-shadow:0 10px 24px rgba(6,34,56,.12);border-color:#c89c4c}
a.j180-tile:focus-visible{outline:3px solid #005577;outline-offset:3px}
.j180-ico{width:60px;height:60px;display:grid;place-items:center;border-radius:16px}
.j180-name{font-size:18px;font-weight:800}
.j180-handle{font-size:14px;font-weight:500;color:#5d6b73;overflow-wrap:anywhere}
.j180-soon{font-size:13px;font-weight:700;color:#8a6420;background:#fff3d6;border:1px solid #c89c4c;border-radius:999px;padding:2px 10px}
.j180-sky{display:block;width:100%;height:auto}
.j180-foot{background:#005577;color:#fff;text-align:center;padding:14px 16px 18px;font-size:15px;font-weight:500}
.j180-foot a{color:#fff;font-weight:800}
@media (prefers-reduced-motion:reduce){.j180-tile{transition:none}a.j180-tile:hover{transform:none}}
`;

function Icon({ a }: { a: Account }) {
  return (
    <span className="j180-ico" aria-hidden="true" style={{ background: a.bg }}>
      <svg viewBox="0 0 24 24" width="32" height="32" fill={a.fg}><path d={a.path} /></svg>
    </span>
  );
}

